import { JsonRpcProvider } from "@ethersproject/providers";
import { getBridgeConfig } from "../consts/bridgeRoutes";
// DONT DECLARE A NEW var here, i think this wont be needed after we update the lowerbound comment i made below
// Extra backlog for the cold-start epoch sweep, so a restart still picks up
// claims that were pending L2 finalization when the bot went down.
const COLD_START_BACKLOG_SECS = 7 * 24 * 60 * 60;

interface EpochRangeParams {
  chainId: number;
  epochPeriod: number;
  currentTimestamp: number;
  now?: number;
  fetchBridgeConfig?: typeof getBridgeConfig;
}

/**
 * Sets the epoch range to check for claims.
 *
 * @param currentTimestamp - The current timestamp
 * @param chainId - The chain ID
 * @param now - The current time in milliseconds (optional, defaults to Date.now())
 * @param fetchBridgeConfig - The function to fetch the bridge configuration (optional, defaults to getBridgeConfig)
 *
 * @returns The epoch range to check for claims
 */

const setEpochRange = ({
  chainId,
  currentTimestamp,
  epochPeriod,
  now = Date.now(),
  fetchBridgeConfig = getBridgeConfig,
}: EpochRangeParams): Array<number> => {
  const { sequencerDelayLimit } = fetchBridgeConfig(chainId);

  // When Sequencer is malicious, even when L1 is finalized, L2 state might be unknown for up to  sequencerDelayLimit + epochPeriod.
  const L2SyncPeriod = sequencerDelayLimit + epochPeriod;
  // When we start the watcher, we need to go back far enough to check for claims which may have been pending L2 state finalization.
  const veaEpochOutboxWatchLowerBound =
    Math.floor((currentTimestamp - L2SyncPeriod - COLD_START_BACKLOG_SECS) / epochPeriod) - 2;
  // ETH / Gnosis POS assumes synchronized clocks
  // using local time as a proxy for true "latest" L1 time
  const timeLocal = Math.floor(now / 1000);

  let veaEpochOutboxClaimableNow = Math.floor(timeLocal / epochPeriod) - 1;
  // only past epochs are claimable, hence shift by one here
  const length = veaEpochOutboxClaimableNow - veaEpochOutboxWatchLowerBound;
  const veaEpochOutboxCheckClaimsRangeArray: number[] = Array.from(
    { length },
    (_, i) => veaEpochOutboxWatchLowerBound + i + 1
  );
  return veaEpochOutboxCheckClaimsRangeArray;
};

const getLatestChallengeableEpoch = (epochPeriod: number, now: number = Date.now()): number => {
  return Math.floor(now / 1000 / epochPeriod) - 2;
};

interface BlockAtTimestampParams {
  provider: JsonRpcProvider;
  timestamp: number;
  floorBlock?: number;
  headBlockTag?: "latest" | "finalized";
}

// Blocks sampled back from the head to observe the chain's recent block rate.
const BLOCK_RATE_SAMPLE_SIZE = 1000;
// Chains differ by orders of magnitude (Arbitrum ~0.25s, Ethereum ~12s), so the
// rate is measured rather than configured. This only guards against divide-by-zero.
const MIN_SECONDS_PER_BLOCK = 0.05;

/**
 * Find the block that contains a given timestamp.
 *
 * Returns the highest block number whose timestamp is at or before `timestamp`.
 *
 * Runs in three steps: estimate where the target sits from the chain's recent
 * block rate, widen that estimate backwards until it really is behind the
 * target, then bisect. The estimate matters because anchoring the search at
 * block 0 would cost a pointless round trip to genesis and make the starting
 * bracket the entire chain; the widening step is what keeps the result correct
 * when the chain's rate has changed and the estimate is therefore wrong.
 *
 * @returns The block number containing `timestamp`
 */
const blockAtTimestamp = async ({
  provider,
  timestamp,
  floorBlock = 0,
  headBlockTag = "finalized",
}: BlockAtTimestampParams): Promise<number> => {
  const headBlock = await provider.getBlock(headBlockTag);
  if (timestamp >= headBlock.timestamp) return headBlock.number;

  const sampleNumber = Math.max(headBlock.number - BLOCK_RATE_SAMPLE_SIZE, floorBlock);
  const sampleBlock = await provider.getBlock(sampleNumber);
  const secondsPerBlock = Math.max(
    (headBlock.timestamp - sampleBlock.timestamp) / Math.max(headBlock.number - sampleNumber, 1),
    MIN_SECONDS_PER_BLOCK
  );

  let span = Math.ceil((headBlock.timestamp - timestamp) / secondsPerBlock);
  let low = Math.max(headBlock.number - span, floorBlock);
  let lowBlock = await provider.getBlock(low);
  while (lowBlock.timestamp > timestamp && low > floorBlock) {
    span *= 2;
    low = Math.max(headBlock.number - span, floorBlock);
    lowBlock = await provider.getBlock(low);
  }
  if (lowBlock.timestamp > timestamp) return floorBlock;

  let high = headBlock.number;
  while (high - low > 1) {
    const middle = Math.floor((low + high) / 2);
    const block = await provider.getBlock(middle);
    if (block.timestamp <= timestamp) low = middle;
    else high = middle;
  }
  return low;
};

interface LookbackFloorParams {
  provider: JsonRpcProvider;
  chainId: number;
  epochPeriod: number;
  headBlockTag?: "latest" | "finalized";
  fetchBridgeConfig?: typeof getBridgeConfig;
}
// Logically the loop back should be limited to the sequencerDelayLimit + epochPeriod, but we add a backlog to account for the time it takes for the bot to start up and catch up with the chain. But i think thats too harsh and we should just use the sequencerDelayLimit + epochPeriod as the limit. Maybe 2 epoch periods?
/**
 * The oldest block worth searching for a "latest event of its kind" lookup.
 *
 * Bounded by the protocol's worst-case L2 sync window. This is a cheap on-chain
 * fast path with an indexer fallback behind it, so it deliberately does not
 * carry the cold-start backlog: `findLatestLog` scans backward with early exit,
 * meaning a wider floor costs nothing when events are recent and costs the most
 * when there are none to find. On Arbitrum the backlog would be ~2.4M blocks of
 * empty scanning before falling back to the indexer anyway.
 *
 * @returns The block number to stop searching backward at
 */
const getLookbackFloorBlock = async ({
  provider,
  chainId,
  epochPeriod,
  headBlockTag = "finalized",
  fetchBridgeConfig = getBridgeConfig,
}: LookbackFloorParams): Promise<number> => {
  const { sequencerDelayLimit } = fetchBridgeConfig(chainId);
  const headBlock = await provider.getBlock(headBlockTag);
  const floorTimestamp = headBlock.timestamp - (sequencerDelayLimit + epochPeriod);
  if (floorTimestamp <= 0) return 0;
  return blockAtTimestamp({ provider, timestamp: floorTimestamp, headBlockTag });
};

/**
 * Get the block number corresponding to a given epoch.
 *
 * @param epoch - The epoch number
 * @param epochPeriod - The epoch period in seconds
 * @param provider - The JSON-RPC provider
 *
 * @returns The block number corresponding to the given epoch
 */
const getBlockFromEpoch = async (epoch: number, epochPeriod: number, provider: JsonRpcProvider): Promise<number> =>
  blockAtTimestamp({ provider, timestamp: epoch * epochPeriod });

export {
  setEpochRange,
  getLatestChallengeableEpoch,
  getBlockFromEpoch,
  blockAtTimestamp,
  getLookbackFloorBlock,
  EpochRangeParams,
};

import {
  ChildTransactionReceipt,
  ArbitrumProvider,
  ChildToParentMessageWriter,
  ChildToParentMessageStatus,
} from "@arbitrum/sdk";
import { Wallet } from "@ethersproject/wallet";
import { JsonRpcProvider, TransactionReceipt } from "@ethersproject/providers";
import { Signer } from "@ethersproject/abstract-signer";
import { ContractTransaction } from "@ethersproject/contracts";

/**
 * Execute the child-to-parent (arbitrum-to-ethereum) message,
 * for reference see: https://docs.arbitrum.io/sdk/reference/message/ChildToParentMessage
 *
 * @param trnxHash Hash of the transaction
 * @param childJsonRpc L2 provider
 * @param parentJsonRpc L1 provider
 * @returns Execution transaction for the message
 *
 * */
async function messageExecutor(
  trnxHash: string,
  childJsonRpc: JsonRpcProvider,
  parentProvider: JsonRpcProvider
): Promise<ContractTransaction> {
  const PRIVATE_KEY = process.env.PRIVATE_KEY;
  const childProvider = new ArbitrumProvider(childJsonRpc);

  const childReceipt: TransactionReceipt = await childProvider.getTransactionReceipt(trnxHash);
  if (!childReceipt) {
    throw new Error(`Transaction receipt not found for hash: ${trnxHash}`);
  }

  const messageReceipt = new ChildTransactionReceipt(childReceipt);
  const parentSigner: Signer = new Wallet(PRIVATE_KEY, parentProvider);

  const messages = await messageReceipt.getChildToParentMessages(parentSigner);
  const childToParentMessage: ChildToParentMessageWriter = messages[0];
  if (!childToParentMessage) {
    throw new Error("No child-to-parent messages found");
  }

  // Execute the message
  const res = await childToParentMessage.execute(childProvider);
  return res;
}

/**
 *
 * @param trnxHash Hash of the transaction
 * @param childJsonRpc L2 provider
 * @param parentJsonRpc L1 provider
 * @returns status of the message: 0 - not ready, 1 - ready
 *
 */
async function getMessageStatus(
  trnxHash: string,
  childJsonRpc: JsonRpcProvider,
  parentJsonRpc: JsonRpcProvider
): Promise<ChildToParentMessageStatus> {
  const PRIVATE_KEY = process.env.PRIVATE_KEY;
  const childProvider = new ArbitrumProvider(childJsonRpc);

  let childReceipt: TransactionReceipt | null;

  childReceipt = await childProvider.getTransactionReceipt(trnxHash);
  if (!childReceipt) {
    throw new Error(`Transaction receipt not found for hash: ${trnxHash}`);
  }
  const messageReceipt = new ChildTransactionReceipt(childReceipt);
  const parentSigner: Signer = new Wallet(PRIVATE_KEY, parentJsonRpc);
  const messages = await messageReceipt.getChildToParentMessages(parentSigner);
  const childToParentMessage = messages[0];
  if (!childToParentMessage) {
    console.error("No child-to-parent messages found");
  }
  const status = await childToParentMessage.status(childProvider);
  return status;
}

export { messageExecutor, getMessageStatus };

import { getSequencerDelaySeconds, resolveSettledReadBlocks } from "./arbToEthState";
import { BotEvents } from "./botEvents";

describe("arbToEthState", () => {
  describe("getSequencerDelaySeconds", () => {
    it("reads delaySeconds out of the maxTimeVariation tuple", async () => {
      // maxTimeVariation returns [delayBlocks, futureBlocks, delaySeconds, futureSeconds]
      // with named accessors, exactly as ethers decodes a multi-value return.
      const tuple: any = [7200, 64, 86400, 768];
      tuple.delayBlocks = 7200;
      tuple.futureBlocks = 64;
      tuple.delaySeconds = 86400;
      tuple.futureSeconds = 768;
      const sequencer: any = { maxTimeVariation: jest.fn(async () => tuple) };

      const delaySeconds = await getSequencerDelaySeconds(sequencer);

      // Coercing the whole tuple yields NaN, which silently poisons every block
      // range derived from it.
      expect(Number.isNaN(delaySeconds)).toBe(false);
      expect(delaySeconds).toBe(86400);
    });
  });

  describe("resolveSettledReadBlocks", () => {
    const epoch = 100;
    const epochPeriod = 7200;
    const epochBoundary = (epoch + 1) * epochPeriod; // 727200

    // Finalized sits comfortably past the boundary; latest runs ~1000s ahead of
    // it, mirroring the real Arbitrum finalized/latest lag.
    const FINALIZED_INBOX = { number: 306_763_304, timestamp: epochBoundary + 4_000 };
    const LATEST_INBOX = { number: 306_767_570, timestamp: epochBoundary + 5_064 };
    const FINALIZED_OUTBOX = { number: 9_000_000, timestamp: epochBoundary + 4_000 };

    const makeProviders = (inboxFinalized: any = FINALIZED_INBOX) => ({
      inboxProvider: {
        getBlock: jest.fn(async (tag: any) => (tag === "finalized" ? inboxFinalized : LATEST_INBOX)),
      } as any,
      outboxProvider: {
        getBlock: jest.fn(async () => FINALIZED_OUTBOX),
      } as any,
    });

    const emitted: any[][] = [];
    const emitter: any = { emit: (...args: any[]) => emitted.push(args) };
    beforeEach(() => (emitted.length = 0));

    const healthyFinality = jest.fn(async () => [FINALIZED_INBOX, FINALIZED_OUTBOX, false, false]) as any;

    it("pins to the finalized inbox block, never the latest one", async () => {
      const { inboxProvider, outboxProvider } = makeProviders();

      const blocks = await resolveSettledReadBlocks({
        inboxProvider,
        outboxProvider,
        epoch,
        epochPeriod,
        emitter,
        fetchBlocksAndCheckFinality: healthyFinality,
      });

      // getBlocksAndCheckFinality hands back the latest block in its happy path;
      // staking a deposit on it exposes the read to an L2 reorg.
      expect(blocks).toEqual({ inboxBlock: FINALIZED_INBOX.number, outboxBlock: FINALIZED_OUTBOX.number });
      expect(blocks!.inboxBlock).not.toBe(LATEST_INBOX.number);
    });

    it("uses the blocks the finality check validated, without re-fetching them", async () => {
      const { inboxProvider, outboxProvider } = makeProviders();

      const blocks = await resolveSettledReadBlocks({
        inboxProvider,
        outboxProvider,
        epoch,
        epochPeriod,
        emitter,
        fetchBlocksAndCheckFinality: healthyFinality,
      });

      // Re-fetching "finalized" would pin to a block the check never saw: the head
      // moves between the two calls, and the fallback provider may answer from a
      // different endpoint entirely.
      expect(inboxProvider.getBlock).not.toHaveBeenCalled();
      expect(outboxProvider.getBlock).not.toHaveBeenCalled();
      expect(blocks).toEqual({ inboxBlock: FINALIZED_INBOX.number, outboxBlock: FINALIZED_OUTBOX.number });
    });

    it("returns null instead of throwing when the finality check yields nothing", async () => {
      const { inboxProvider, outboxProvider } = makeProviders();

      const blocks = await resolveSettledReadBlocks({
        inboxProvider,
        outboxProvider,
        epoch,
        epochPeriod,
        emitter,
        fetchBlocksAndCheckFinality: jest.fn(async () => undefined) as any,
      });

      expect(blocks).toBeNull();
      expect(emitted.some((e) => e[0] === BotEvents.FINALITY_ISSUE)).toBe(true);
    });

    it.each([
      ["arbitrum", [FINALIZED_INBOX, FINALIZED_OUTBOX, true, false]],
      ["ethereum", [FINALIZED_INBOX, FINALIZED_OUTBOX, false, true]],
    ])("refuses to decide while %s finality is flagged", async (_name, result) => {
      const { inboxProvider, outboxProvider } = makeProviders();

      const blocks = await resolveSettledReadBlocks({
        inboxProvider,
        outboxProvider,
        epoch,
        epochPeriod,
        emitter,
        fetchBlocksAndCheckFinality: jest.fn(async () => result) as any,
      });

      expect(blocks).toBeNull();
      expect(emitted.some((e) => e[0] === BotEvents.FINALITY_ISSUE)).toBe(true);
    });

    it("refuses when the finalized inbox block still predates the epoch boundary", async () => {
      // snapshots[epoch] is written during epoch E, so a block inside epoch E can
      // hold a partial snapshot and would make an honest claim look fraudulent.
      const tooEarly = { number: 306_000_000, timestamp: epochBoundary - 1 };
      const { inboxProvider, outboxProvider } = makeProviders();

      const blocks = await resolveSettledReadBlocks({
        inboxProvider,
        outboxProvider,
        epoch,
        epochPeriod,
        emitter,
        fetchBlocksAndCheckFinality: jest.fn(async () => [tooEarly, FINALIZED_OUTBOX, false, false]) as any,
      });

      expect(blocks).toBeNull();
      expect(emitted.some((e) => e[0] === BotEvents.EPOCH_NOT_SETTLED)).toBe(true);
    });

    it("accepts a finalized block exactly on the epoch boundary", async () => {
      const onBoundary = { number: 306_500_000, timestamp: epochBoundary };
      const { inboxProvider, outboxProvider } = makeProviders();

      const blocks = await resolveSettledReadBlocks({
        inboxProvider,
        outboxProvider,
        epoch,
        epochPeriod,
        emitter,
        fetchBlocksAndCheckFinality: jest.fn(async () => [onBoundary, FINALIZED_OUTBOX, false, false]) as any,
      });

      expect(blocks).toEqual({ inboxBlock: onBoundary.number, outboxBlock: FINALIZED_OUTBOX.number });
    });

    it("reads outboxBlock from the outbox chain, not from the L1 chain used for Arbitrum finality", async () => {
      // arbToGnosis: Arbitrum's finality is anchored on Sepolia (11155111), but
      // the outbox contract itself lives on Chiado (10200). The L1 provider's
      // "finalized" block is a Sepolia block number; claimHashes(epoch) on the
      // Chiado outbox must never be read with it.
      const SEPOLIA_CHAIN_ID = 11155111;
      const CHIADO_CHAIN_ID = 10200;
      const SEPOLIA_L1_FINALIZED = { number: 7_000_000, timestamp: epochBoundary + 4_000, chainId: SEPOLIA_CHAIN_ID };
      const CHIADO_OUTBOX_FINALIZED = {
        number: 33_000_000,
        timestamp: epochBoundary + 4_000,
        chainId: CHIADO_CHAIN_ID,
      };

      const { inboxProvider, outboxProvider: l1Provider } = makeProviders();
      // The router/L1 finality check never talks to the outbox chain directly.
      const outboxChainProvider = {
        getBlock: jest.fn(async (tag: any) => {
          expect(tag).toBe("finalized");
          return CHIADO_OUTBOX_FINALIZED;
        }),
      } as any;
      const fetchBlocksAndCheckFinality = jest.fn(
        async () => [FINALIZED_INBOX, SEPOLIA_L1_FINALIZED, false, false]
      ) as any;

      const blocks = await resolveSettledReadBlocks({
        inboxProvider,
        outboxProvider: l1Provider,
        outboxChainProvider,
        epoch,
        epochPeriod,
        emitter,
        fetchBlocksAndCheckFinality,
      });

      expect(outboxChainProvider.getBlock).toHaveBeenCalledWith("finalized");
      // outboxBlock must be the Chiado block, never the Sepolia L1 block the
      // finality check returned.
      expect(blocks!.outboxBlock).toBe(CHIADO_OUTBOX_FINALIZED.number);
      expect(blocks!.outboxBlock).not.toBe(SEPOLIA_L1_FINALIZED.number);
      expect(blocks).toEqual({ inboxBlock: FINALIZED_INBOX.number, outboxBlock: CHIADO_OUTBOX_FINALIZED.number });
    });
  });
});

import {
  VeaInboxArbToGnosis,
  VeaOutboxArbToGnosis,
  VeaOutboxArbToGnosisDevnet,
} from "../../../../contracts/typechain-types";
import { toBigInt, Wallet } from "ethers";
import {
  BaseTransactionHandler,
  BaseTransactionHandlerConstructor,
  ContractType,
  Transaction,
  Transactions,
} from "./baseTransactionHandler";
import { BotEvents } from "../botEvents";
import { ClaimNotSetError } from "../errors";
import { getBridgeConfig, Network } from "../../consts/bridgeRoutes";
import { getWETH } from "../ethers";
import { messageExecutor } from "../arbMsgExecutor";

export class ArbToGnosisTransactionHandler extends BaseTransactionHandler<VeaInboxArbToGnosis, VeaOutboxArbToGnosis> {
  constructor(opts: BaseTransactionHandlerConstructor) {
    super(opts);
  }

  public async approveWeth(): Promise<void> {
    const { depositToken, routeConfig } = getBridgeConfig(this.chainId);
    const { veaOutbox, deposit } = routeConfig[this.network];
    const signer = this.veaOutbox.runner as Wallet;

    const weth = getWETH(depositToken, signer);
    const currentAllowance: bigint = await weth.allowance(signer.address, veaOutbox.address);
    if (currentAllowance < deposit) {
      const approvalAmount = deposit * BigInt(10); // Approving for 10 claims
      const approveTx = await weth.approve(veaOutbox.address, approvalAmount);
      await approveTx.wait();
    }
  }

  public async makeClaim(stateRoot: string): Promise<void> {
    this.emitter.emit(BotEvents.CLAIMING, this.epoch);
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.claimTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;

    // Approves WETH for the claim if not already approved
    await this.approveWeth();

    const gasEstimate = await this.veaOutbox["claim(uint256,bytes32)"].estimateGas(this.epoch, stateRoot);
    const tx = await this.veaOutbox.claim(this.epoch, stateRoot, { gasLimit: gasEstimate });
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Claim");
    this.transactions.claimTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }

  public async challengeClaim(): Promise<void> {
    this.emitter.emit(BotEvents.CHALLENGING, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.challengeTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;

    const gasEstimate = await this.veaOutbox[
      "challenge(uint256,(bytes32,address,uint32,uint32,uint32,uint8,address))"
    ].estimateGas(this.epoch, this.claim);
    const { routeConfig } = getBridgeConfig(this.chainId);
    const { deposit } = routeConfig[this.network];
    const maxFeePerGasProfitable = deposit / (toBigInt(gasEstimate) * BigInt(6));
    // Set a reasonable maxPriorityFeePerGas but ensure it's lower than maxFeePerGas
    let maxPriorityFeePerGasMEV = BigInt(6667000000000); // 6667 gwei
    // Ensure maxPriorityFeePerGas <= maxFeePerGas
    if (maxPriorityFeePerGasMEV > maxFeePerGasProfitable) {
      maxPriorityFeePerGasMEV = maxFeePerGasProfitable;
    }
    const tx = await this.veaOutbox.challenge(this.epoch, this.claim, {
      maxFeePerGas: maxFeePerGasProfitable,
      maxPriorityFeePerGas: maxPriorityFeePerGasMEV,
      gasLimit: gasEstimate,
    });
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Challenge");
    this.transactions.challengeTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }

  public async sendSnapshot(): Promise<void> {
    this.emitter.emit(BotEvents.SENDING_SNAPSHOT, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.sendSnapshotTxn, ContractType.INBOX, now);
    if (!toSubmit) return;

    const ambGasLimit = BigInt(3000000);
    const tx = await this.veaInbox.sendSnapshot(this.epoch, ambGasLimit, this.claim);
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Send Snapshot");
    this.transactions.sendSnapshotTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }

  public async resolveChallengedClaim(sendSnapshotTxn: string): Promise<void> {
    this.emitter.emit(BotEvents.EXECUTING_SNAPSHOT, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.executeSnapshotTxn, ContractType.ROUTER, now);
    if (!toSubmit) return;
    const msgExecuteTrnx = await messageExecutor(sendSnapshotTxn, this.veaInboxProvider, this.veaRouterProvider);
    this.emitter.emit(BotEvents.TXN_MADE, msgExecuteTrnx.hash, this.epoch, "Execute Snapshot");
    this.transactions.executeSnapshotTxn = {
      hash: msgExecuteTrnx.hash,
      broadcastedTimestamp: now,
    };
  }
}

/**
 * Devnet-only extension for Arb→Gnosis handler
 */
export interface GnosisDevnetTransactions extends Transactions {
  devnetAdvanceStateTxn: Transaction | null;
}

export class ArbToGnosisDevnetTransactionHandler extends ArbToGnosisTransactionHandler {
  public veaOutboxDevnet: VeaOutboxArbToGnosisDevnet;
  public transactions: GnosisDevnetTransactions = {
    ...(this.transactions as Transactions),
    devnetAdvanceStateTxn: null,
  };

  constructor(opts: BaseTransactionHandlerConstructor) {
    super(opts);
    this.veaOutboxDevnet = opts.veaOutbox as VeaOutboxArbToGnosisDevnet;
  }

  /**
   * Advance the devnet state via a special call on the Devnet outbox.
   */
  public async devnetAdvanceState(stateRoot: string): Promise<void> {
    this.emitter.emit(BotEvents.ADV_DEVNET, this.epoch);
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.devnetAdvanceStateTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;
    await this.approveWeth();
    const { routeConfig } = getBridgeConfig(this.chainId);
    const { deposit } = routeConfig[Network.DEVNET];
    const tx = await this.veaOutboxDevnet.devnetAdvanceState(this.epoch, stateRoot, {
      value: deposit,
    });
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Advance Devnet State");
    this.transactions.devnetAdvanceStateTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }
}

import { VeaInboxArbToEth, VeaOutboxArbToEth, VeaOutboxArbToEthDevnet } from "../../../../contracts/typechain-types";
import { toBigInt } from "ethers";
import {
  BaseTransactionHandler,
  BaseTransactionHandlerConstructor,
  ContractType,
  Transaction,
  Transactions,
} from "./baseTransactionHandler";
import { BotEvents } from "../../utils/botEvents";
import { ClaimNotSetError } from "../../utils/errors";
import { getBridgeConfig, Network } from "../../consts/bridgeRoutes";
import { messageExecutor } from "../../utils/arbMsgExecutor";

// Handler for Arbitrum → Ethereum claims and snapshots, now leveraging BaseTransactionHandler
export class ArbToEthTransactionHandler extends BaseTransactionHandler<VeaInboxArbToEth, VeaOutboxArbToEth> {
  constructor(opts: BaseTransactionHandlerConstructor) {
    super(opts);
  }

  /**
   * Make a claim on the Ethereum outbox.
   */
  public async makeClaim(stateRoot: string): Promise<void> {
    this.emitter.emit(BotEvents.CLAIMING, this.epoch);
    const now = Date.now();

    const toSubmit = await this.toSubmitTransaction(this.transactions.claimTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;

    const { routeConfig } = getBridgeConfig(this.chainId);
    const { deposit } = routeConfig[this.network];
    // Estimate gas and send claim with deposit
    const gasLimit = await this.veaOutbox["claim(uint256,bytes32)"].estimateGas(this.epoch, stateRoot, {
      value: deposit,
    });
    const tx = await this.veaOutbox.claim(this.epoch, stateRoot, {
      value: deposit,
      gasLimit,
    });
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Claim");
    this.transactions.claimTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }

  /**
   * Challenge an existing claim on the Ethereum outbox.
   */
  public async challengeClaim(): Promise<void> {
    this.emitter.emit(BotEvents.CHALLENGING, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.challengeTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;

    const { routeConfig } = getBridgeConfig(this.chainId);
    const { deposit } = routeConfig[this.network];
    const gasEstimate = await this.veaOutbox[
      "challenge(uint256,(bytes32,address,uint32,uint32,uint32,uint8,address))"
    ].estimateGas(this.epoch, this.claim, { value: deposit });

    // Profit-driven fee calculation
    const maxFeePerGas = deposit / (toBigInt(gasEstimate) * BigInt(6));
    let maxPriorityFeePerGas = BigInt(6_667_000_000_000);
    if (maxPriorityFeePerGas > maxFeePerGas) {
      maxPriorityFeePerGas = maxFeePerGas;
    }

    const tx = await this.veaOutbox["challenge(uint256,(bytes32,address,uint32,uint32,uint32,uint8,address))"](
      this.epoch,
      this.claim,
      {
        maxFeePerGas,
        maxPriorityFeePerGas,
        value: deposit,
        gasLimit: gasEstimate,
      }
    );

    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Challenge");
    this.transactions.challengeTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }

  /**
   * Send a snapshot from Arbitrum inbox to Ethereum outbox.
   */
  public async sendSnapshot(): Promise<void> {
    this.emitter.emit(BotEvents.SENDING_SNAPSHOT, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();

    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.sendSnapshotTxn, ContractType.INBOX, now);
    if (!toSubmit) return;

    const tx = await this.veaInbox.sendSnapshot(this.epoch, this.claim);
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Send Snapshot");
    this.transactions.sendSnapshotTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }

  /**
   * Execute a challenged snapshot via the messageExecutor utility.
   */
  public async resolveChallengedClaim(sendSnapshotHash: string, execFn = messageExecutor): Promise<void> {
    this.emitter.emit(BotEvents.EXECUTING_SNAPSHOT, this.epoch);
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.executeSnapshotTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;

    const result = await execFn(sendSnapshotHash, this.veaInboxProvider, this.veaOutboxProvider);
    this.emitter.emit(BotEvents.TXN_MADE, result.hash, this.epoch, "Execute Snapshot");
    this.transactions.executeSnapshotTxn = { hash: result.hash, broadcastedTimestamp: now };
  }
}

